import sys

def two_sum(nums, target):
    lookup = {}
    for i, num in enumerate(nums):
        diff = target - num
        if diff in lookup:
            return f"{lookup[diff]},{i}"
        lookup[num] = i
    return ""

if __name__ == '__main__':
    lines = sys.stdin.read().splitlines()
    if len(lines) >= 2:
        nums = list(map(int, lines[0].split(',')))
        target = int(lines[1])
        print(two_sum(nums, target))

