import sys
lines = sys.stdin.read().splitlines()
if len(lines) >= 2:
    coins = list(map(int, lines[0].split(',')))
    amt = int(lines[1])
    dp = [float('inf')] * (amt + 1)
    dp[0] = 0
    for a in range(1, amt + 1):
        for c in coins:
